// ============================================================
// GATEWAY: Rate Limiter + Spam Protection (v4.0)
// + Circuit Breaker для защиты от каскадных сбоев
// ============================================================

const input = $input.first().json;
const isCallback = !!input.callback_query;
const message = isCallback ? input.callback_query.message : input.message;
const from = isCallback ? input.callback_query.from : input.message?.from;

// Валидация входных данных
if (!from?.id) {
  return [{
    blocked: true,
    reason: 'no_user_id',
    message: '⚠️ Ошибка идентификации. Попробуйте позже.',
    chat_id: message?.chat?.id || 0
  }];
}

const userId = from.id;
const chatId = message?.chat?.id || from.id;
const text = isCallback ? '' : (input.message?.text || '');
const callbackData = isCallback ? input.callback_query.data : null;

const now = Date.now();
const windowMs = 60000;
const maxRequests = 15;
const blockDurationMs = 120000;

// Получаем глобальное хранилище
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};
if (!staticData.circuitBreaker) {
  staticData.circuitBreaker = {
    failures: 0,
    lastFailure: 0,
    isOpen: false,
    openUntil: 0
  };
}

const limits = staticData.rateLimits;
const cb = staticData.circuitBreaker;

// Circuit Breaker: проверка состояния
if (cb.isOpen && now < cb.openUntil) {
  return [{
    blocked: true,
    reason: 'circuit_breaker',
    message: '🔧 Система временно недоступна. Пожалуйста, попробуйте через несколько минут.',
    chat_id: chatId,
    user_id: userId
  }];
}

// Сброс circuit breaker если время вышло
if (cb.isOpen && now >= cb.openUntil) {
  cb.isOpen = false;
  cb.failures = 0;
}

// Очистка старых записей rate limit
if (!staticData.lastCleanup || now - staticData.lastCleanup > 300000) {
  Object.keys(limits).forEach(uid => {
    if (now > (limits[uid].resetTime || 0) + 300000) {
      delete limits[uid];
    }
  });
  staticData.lastCleanup = now;
}

// Rate limiting
if (!limits[userId]) {
  limits[userId] = { count: 0, resetTime: now + windowMs, blocked_until: 0 };
}

const userLimits = limits[userId];

if (now < userLimits.blocked_until) {
  const waitSec = Math.ceil((userLimits.blocked_until - now) / 1000);
  return [{
    blocked: true,
    reason: 'rate_limit',
    message: `⏳ Подождите ${waitSec} сек. перед следующим сообщением.`,
    chat_id: chatId,
    user_id: userId
  }];
}

if (now > userLimits.resetTime) {
  userLimits.count = 0;
  userLimits.resetTime = now + windowMs;
}

userLimits.count++;

if (userLimits.count > maxRequests) {
  userLimits.blocked_until = now + blockDurationMs;
  return [{
    blocked: true,
    reason: 'spam',
    message: '🚫 Слишком много сообщений. Подождите 2 минуты.',
    chat_id: chatId,
    user_id: userId
  }];
}

// Проверка на спам-контент
const spamPatterns = [
  /http[s]?:\/\//i,
  /t\.me\//i,
  /@\w{5,}/,
  /[А-Яа-яA-Za-z]{50,}/
];

if (spamPatterns.some(p => p.test(text)) && !isCallback) {
  return [{
    blocked: true,
    reason: 'spam_content',
    message: '⚠️ Сообщение заблокировано. Пожалуйста, отправьте текст без ссылок.',
    chat_id: chatId,
    user_id: userId
  }];
}

// Всё OK
return [{
  blocked: false,
  chat_id: chatId,
  user_id: userId,
  text: text,
  first_name: from?.first_name || '',
  username: from?.username || '',
  is_callback: isCallback,
  callback_data: callbackData,
  timestamp: now,
  message_id: message?.message_id || null
}];

// Успешный ответ - сбрасываем счётчик ошибок circuit breaker
const staticData = $getWorkflowStaticData('global');
if (staticData.circuitBreaker) {
  staticData.circuitBreaker.failures = 0;
}

const data = $json;
console.log('📥 GATEWAY SUCCESS:', {
  user_id: data.user_id,
  text: data.text?.substring(0, 50)
});
return data;

// ============================================================
// GATEWAY ERROR HANDLER: Circuit Breaker Logic
// ============================================================

const staticData = $getWorkflowStaticData('global');
const cb = staticData.circuitBreaker || { failures: 0, lastFailure: 0, isOpen: false, openUntil: 0 };
const now = Date.now();

// Увеличиваем счётчик ошибок
cb.failures++;
cb.lastFailure = now;

// Если 5+ ошибок за последние 2 минуты - открываем circuit breaker на 3 минуты
if (cb.failures >= 5) {
  cb.isOpen = true;
  cb.openUntil = now + 180000; // 3 минуты
  console.log('🔴 CIRCUIT BREAKER OPENED - too many failures');
}

staticData.circuitBreaker = cb;

// Получаем данные пользователя из предыдущего узла
const input = $('IF Blocked').first().json;

return {
  chat_id: input.chat_id,
  user_id: input.user_id,
  error: true,
  message: '😔 Произошла временная ошибка. Пожалуйста, попробуйте ещё раз через минуту.\n\nЕсли проблема повторяется, напишите /start для перезапуска.',
  failures: cb.failures
};
